async function scan(c){let aliases={'Dow':'Dow Inc','Gap':'Gap Inc','Target':'Target Corporation','Block':'Block Inc','Southern':'Southern Company','Williams':'Williams Companies','Travelers':'Travelers Insurance'};let identity=aliases[c.name]||c.name;let query='"'+identity+'" AI';let url='https://www.bing.com/news/search?q='+encodeURIComponent(query)+'&format=rss';try{let r=await fetch(url,{signal:AbortSignal.timeout(10000),headers:{'user-agent':'Mozilla/5.0 AI-Spend-Radar/1.0'}});if(!r.ok)throw Error('feed '+r.status);let xml=await r.text();let norm=x=>String(x||'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();let needle=norm(identity),cutoff=Date.now()-180*86400000;let stories=[...xml.matchAll(/<item>([\s\S]*?)<\/item>/g)].map(m=>{let y=m[1],title=tag(y,'title'),link=tag(y,'link'),published=tag(y,'pubDate');let plain=norm(title);let related=plain.includes(needle)&&/\b(ai|artificial intelligence|machine learning|generative)\b/i.test(title)&&!(/\b(stock|shares|futures|market today|buy points|price target|outperform|selloff|sell-off|rebound|plunge|rally|bullish|bearish|investors|investment case|trading|billionaire|hedge funds|analysts|buyback|portfolio|dow jones)\b/i.test(title));let recent=!published||Date.parse(published)>=cutoff;let spendRelated=/\b(spend|spending|invest|investment|fund|funding|budget|capex|million|billion)\w*/i.test(title);let target=link.match(/[?&]url=([^&]+)/)?.[1];return{title,url:target?decodeURIComponent(target):link,published,publisher:tag(y,'News:Source'),amount:null,kind:spendRelated?'Spending mention':'AI mention',related,recent}}).filter(v=>v.title&&v.url&&v.related&&v.recent).slice(0,6).map(({related,recent,...v})=>v);return{...c,stories,signals:stories.length,status:'live'}}catch(e){return{...c,status:'unavailable',error:String(e)}}}
const page=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Spend Radar</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Libre+Franklin:wght@500;700;800&display=swap" rel="stylesheet"><style>:root{--ink:#17352b;--muted:#586e62;--line:#d5e0d8;--green:#146444;--bg:#f5f7f2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 'DM Sans',sans-serif}header{background:#173f31;color:white;padding:17px max(20px,calc((100vw - 1420px)/2));display:flex;justify-content:space-between;gap:20px}header a{color:#e1f0e7;font-size:13px;text-decoration:none;border:1px solid #618472;border-radius:6px;padding:7px 10px}header a:hover{text-decoration:underline}header strong{font:800 20px 'Libre Franklin',sans-serif;letter-spacing:-.03em}header span{font-size:13px;color:#c2decf}main{max-width:1460px;padding:35px 20px 80px;margin:auto}h1{font:800 clamp(30px,4vw,54px)/1.1 'Libre Franklin',sans-serif;letter-spacing:-.035em;max-width:850px;margin:0 0 13px}h2{font:800 27px 'Libre Franklin',sans-serif;letter-spacing:-.025em;margin:0 0 8px}h3{font:700 16px 'Libre Franklin',sans-serif;margin:23px 0 10px}p{color:var(--muted)}.intro{display:flex;justify-content:space-between;gap:20px;align-items:end;border-bottom:1px solid var(--line);padding-bottom:25px}.intro p{max-width:730px;margin:0}.updated{white-space:nowrap;color:var(--muted);font-size:13px}.bar{display:flex;gap:10px;flex-wrap:wrap;margin:23px 0}.bar input,.bar select,.detail select{padding:10px 12px;border:1px solid var(--line);background:white;border-radius:7px;color:var(--ink);font:inherit}.bar input{flex:1;min-width:220px;max-width:380px}button{font:inherit;cursor:pointer}.primary{border:0;border-radius:7px;background:var(--green);color:white;padding:10px 17px;font-weight:700}.primary:hover{background:#0e5036}.primary:disabled{opacity:.6}.status{align-self:center;color:var(--muted);font-size:13px;margin-left:auto}.note{background:#e7f0e9;padding:13px 16px;border-radius:8px;color:#2b5640;font-size:13px;margin-bottom:20px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 440px;gap:20px;align-items:start}.list,.detail{background:white;border:1px solid var(--line);border-radius:12px;overflow:hidden}.head,.row{display:grid;grid-template-columns:33px minmax(140px,1fr) 110px 72px 88px;gap:10px;align-items:center;padding:12px 15px}.head{background:#eaf0e9;color:var(--muted);font-weight:700;font-size:11px;text-transform:uppercase;letter-spacing:.05em}.row{width:100%;border:0;border-top:1px solid #e9eee9;background:white;text-align:left;color:var(--ink)}.row:hover,.row.active{background:#f0f7f1}.name{font-weight:700}.sector,.rank{color:var(--muted);font-size:12px}.signals{font-weight:700;color:var(--green)}.amount{font-weight:700;color:#a05019}.detail{position:sticky;top:16px;padding:23px;max-height:calc(100vh - 32px);overflow:auto}.pill{display:inline-block;padding:4px 8px;background:#e7f0e9;color:var(--green);border-radius:5px;font-size:11px;font-weight:700;text-transform:uppercase}.story{border-top:1px solid var(--line);padding:11px 0}.story a{font-weight:600;color:var(--green);text-decoration:none}.story a:hover{text-decoration:underline}.story small{display:block;color:var(--muted);margin-top:4px}.detail select{width:100%;margin:6px 0 10px}.email{white-space:pre-wrap;background:#f5f7f3;border:1px solid var(--line);border-radius:8px;padding:13px;font-size:13px;line-height:1.6}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.actions a{color:var(--ink);border:1px solid var(--line);border-radius:7px;padding:9px 13px;text-decoration:none}.foot{font-size:12px;max-width:950px;margin-top:25px}::selection{background:#c2e6d1;color:#12291c}:focus-visible{outline:3px solid #d78d52;outline-offset:2px}@media(max-width:1050px){.layout{grid-template-columns:1fr}.detail{position:static;max-height:none}}@media(max-width:650px){header{padding:15px}header span{display:none}.intro{display:block}.updated{margin-top:13px}.head,.row{grid-template-columns:25px minmax(110px,1fr) 50px 70px;gap:5px;padding:11px 9px}.head .sector,.row .sector{display:none}.bar input{min-width:100%}.status{margin-left:0}.detail{padding:17px}}.chartPanel{background:white;border:1px solid var(--line);border-radius:12px;padding:22px;margin:24px 0}.chartTop{display:flex;justify-content:space-between;gap:20px;align-items:start}.chartTop p{font-size:13px;max-width:750px;margin:3px 0 0}.chartTop a{font-size:13px;color:var(--green);white-space:nowrap}.chart{height:260px;margin-top:15px;overflow:hidden}.chart svg{width:100%;height:100%}.chart circle{cursor:pointer}.chart circle:hover{stroke-width:3}.chartLegend{display:flex;gap:19px;flex-wrap:wrap;font-size:12px;color:var(--muted);margin-top:8px}.chartLegend span{display:flex;gap:7px;align-items:center}.bubble{width:12px;height:12px;border-radius:50%;display:inline-block}.bubble.filled{background:#c98044;border:1px solid #9d592a}.bubble.empty{background:white;border:2px solid #387c56}@media(max-width:650px){.chartPanel{padding:15px}.chartTop{display:block}.chartTop a{display:inline-block;margin-top:10px}.chart{height:240px;overflow-x:auto}.chart svg{min-width:680px}}
.summary{display:flex;gap:0;background:#173f31;color:white;border-radius:12px;margin:22px 0 0;overflow:hidden}.summary div{padding:16px 24px;min-width:190px;flex:1;display:flex;flex-direction:column;border-right:1px solid #45695b}.summary strong{font:800 25px 'Libre Franklin',sans-serif;line-height:1.1;font-variant-numeric:tabular-nums}.summary span{color:#c2decf;font-size:12px;margin-top:4px}.quiet{border:1px solid var(--line);background:white;color:var(--green);padding:10px 14px;border-radius:7px;font-weight:700}.quiet:hover{background:#e7f0e9}.pager{display:flex;justify-content:space-between;align-items:center;padding:10px 15px;color:var(--muted);font-size:12px;border-top:1px solid var(--line)}.pager div{display:flex;gap:6px}.pager button{background:white;border:1px solid var(--line);padding:5px 9px;border-radius:5px;color:var(--ink)}.pager button:disabled{opacity:.4;cursor:default}.chart text{pointer-events:none}.chartPanel{margin-top:22px}.intro{border:0;padding-bottom:0}.intro h1{font-size:clamp(29px,3.3vw,47px);max-width:770px}.note{background:transparent;border-top:1px solid var(--line);border-bottom:1px solid var(--line);border-radius:0;color:var(--muted);padding:11px 0}.layout{grid-template-columns:minmax(0,1fr) 420px}.detail{max-height:calc(100vh - 32px)}@media(max-width:700px){.summary{display:grid;grid-template-columns:1fr 1fr}.summary div{min-width:0;padding:13px}.summary div:last-child{grid-column:1/3;border-top:1px solid #45695b}.bar{margin:18px 0}.quiet{width:100%}.chart{height:240px}.chartPanel{padding:16px}}
</style></head><body><header><strong>AI Spend Radar</strong><span>Current signals · Source-linked outreach</span><a href="https://github.com/shahanvik-tech/ai-spend-radar" target="_blank" rel="noopener noreferrer">GitHub ↗</a></header><main><div class="intro"><div><h1>Find companies investing in AI. Start the right conversation.</h1><p>Explore companies ranked 101–500 in the 2026 Fortune 500, compare AI news mentions and see which companies have sourced spending figures, and draft a relevant email.</p></div><div id="updated" class="updated">Loading current news…</div></div><div class="summary" aria-label="Coverage summary"><div><strong id="covered">400</strong><span>companies covered</span></div><div><strong id="active">—</strong><span>with AI news mentions</span></div><div><strong id="spendMentions">—</strong><span>companies with spending mentions</span></div><div><strong id="figures">—</strong><span>verified spend figures</span></div></div><section class="chartPanel"><div class="chartTop"><div><h2>Fortune 500 AI activity map · ranks 101–500</h2><p>Fortune rank runs left to right. Higher points have more company-linked AI news mentions. Bubble area represents story count, not dollars spent. The top 40 by spending mentions and news volume are plotted.</p></div><a href="https://fortune.com/ranking/fortune500/" target="_blank" rel="noopener noreferrer">2026 Fortune 500 source ↗</a></div><div id="chart" class="chart" role="img" aria-label="Bubble chart of Fortune rank and AI news mentions"></div><div class="chartLegend"><span><i class="bubble filled"></i> Company-linked AI news</span><span><span id="missing">Companies without matched stories are not plotted</span></span><span>Click a point to open company details</span></div></section><div class="bar"><input id="search" placeholder="Search company or sector" aria-label="Search company or sector"><select id="sector" aria-label="Sector"><option value="">All sectors</option></select><select id="sort" aria-label="Sort"><option value="signals">Spending mentions, then AI news</option><option value="name">Company name</option></select><button id="refresh" class="primary">Scan 400 companies</button><button id="coverage" class="quiet" type="button">Show all 400 companies</button><span id="status" class="status">Starting scan…</span></div><div class="note"><strong>How ranking works:</strong> Signals include company-linked AI mentions in news over roughly the last 180 days. A spending mention label means the headline contains a spending or investment term; it does not verify a dollar amount. No matched story does not mean zero AI spend. Reported figures are total capital expenditure guidance from company sources, not AI-only spend. Open the source before using a figure.</div><div class="layout"><section class="list"><div class="head"><span>F#</span><span>Company</span><span class="sector">Sector</span><span>Signals</span><span>Spend mentions</span></div><div id="rows" style="padding:20px">Loading dated scan and checking for updates…</div><div id="pager" class="pager"></div></section><aside id="detail" class="detail"><h2>Select a company</h2><p>Current stories and an outreach draft will appear here.</p></aside></div><p class="foot">The dated snapshot and broad scan use public news links; the broad scan checks Bing News RSS in batches when available. Headlines are discovery leads, not verified AI spending disclosures. This site does not send emails or identify a contact automatically. Check the source and recipient before sending. News feed and publisher availability vary.</p></main><script>const $=s=>document.querySelector(s);let data=[],chosen=null,showAll=false,pageNum=0;const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function filtered(){let q=$('#search').value.toLowerCase(),sector=$('#sector').value;let x=data.filter(c=>(showAll||q||sector||c.signals>0)&&(!sector||c.sector===sector)&&(!q||(c.name+' '+c.sector).toLowerCase().includes(q)));x.sort($('#sort').value==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>b.stories.filter(s=>s.kind==='Spending mention').length-a.stories.filter(s=>s.kind==='Spending mention').length||b.signals-a.signals||a.name.localeCompare(b.name));return x}function rows(){let all=filtered(),x=all.slice(pageNum*25,(pageNum+1)*25);$('#rows').style.padding=x.length?'0':'20px';$('#rows').innerHTML=x.length?x.map((c,i)=>'<button class="row '+(chosen===c.id?'active':'')+'" data-id="'+c.id+'"><span class="rank">'+String(c.fortuneRank).padStart(2,'0')+'</span><span class="name">'+esc(c.name)+'</span><span class="sector">'+esc(c.sector)+'</span><span class="signals">'+c.signals+'</span><span class="amount">'+(c.stories.filter(s=>s.kind==='Spending mention').length||'—')+'</span></button>').join(''):'No companies match.';document.querySelectorAll('.row').forEach(b=>b.onclick=()=>{chosen=+b.dataset.id;rows();chart();detail()});$('#pager').innerHTML=all.length>25?'<span>Showing '+(pageNum*25+1)+'–'+Math.min((pageNum+1)*25,all.length)+' of '+all.length+'</span><div><button id="prev" '+(pageNum?'':'disabled')+'>Previous</button><button id="next" '+((pageNum+1)*25<all.length?'':'disabled')+'>Next</button></div>':'';if($('#prev'))$('#prev').onclick=()=>{pageNum--;rows()};if($('#next'))$('#next').onclick=()=>{pageNum++;rows()}}function chart(){let found=filtered().filter(c=>c.signals>0).slice(0,40),max=Math.max(4,...data.map(c=>c.signals));let W=1000,H=260,L=50,R=22,T=24,B=42;let x=c=>L+(c.fortuneRank-101)/399*(W-L-R),y=c=>H-B-c.signals/max*(H-T-B);let grid=[0,Math.ceil(max/2),max].map(n=>'<line x1="'+L+'" x2="'+(W-R)+'" y1="'+(H-B-n/max*(H-T-B))+'" y2="'+(H-B-n/max*(H-T-B))+'" stroke="#dae5dd"/><text x="'+(L-8)+'" y="'+(H-B-n/max*(H-T-B)+4)+'" text-anchor="end" fill="#62746a" font-size="11">'+n+'</text>').join('');let ticks=[101,200,300,400,500].map(n=>'<text x="'+(L+(n-101)/399*(W-L-R))+'" y="'+(H-12)+'" text-anchor="middle" fill="#62746a" font-size="11">'+n+'</text>').join('');let dots=found.map(c=>{let r=c.signals?Math.max(6,Math.sqrt(c.signals)*4):4;let spendHit=c.stories.some(s=>s.kind==='Spending mention');return '<circle tabindex="0" role="button" aria-label="'+esc(c.name)+', Fortune rank '+c.fortuneRank+', '+c.signals+' AI news mentions'+' " data-company="'+c.id+'" cx="'+x(c)+'" cy="'+y(c)+'" r="'+r+'" fill="'+(spendHit?'#c98044':'#5c9582')+'" fill-opacity="'+(chosen===c.id?'1':'.62')+'" stroke="'+(chosen===c.id?'#173f31':spendHit?'#9d592a':'#28705b')+'" stroke-width="'+(chosen===c.id?'3':'1.5')+'"><title>'+esc(c.name)+' · #'+c.fortuneRank+' · '+c.signals+' signals'+'</title></circle>'+(c.id===chosen?'<text x="'+x(c)+'" y="'+(y(c)-r-7)+'" text-anchor="middle" fill="#17352b" font-size="12" font-weight="700">'+esc(c.name)+'</text>':'')}).join('');$('#chart').innerHTML='<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" aria-hidden="true">'+grid+ticks+dots+'<text x="'+(W/2)+'" y="'+(H-1)+'" text-anchor="middle" fill="#62746a" font-size="12">Fortune 500 rank →</text><text x="16" y="'+(H/2)+'" transform="rotate(-90 16 '+(H/2)+')" text-anchor="middle" fill="#62746a" font-size="12">AI news mentions</text></svg>';document.querySelectorAll('[data-company]').forEach(el=>{let select=()=>{chosen=+el.dataset.company;rows();chart();detail()};el.onclick=select;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select()}}})}
function detail(){let c=data.find(v=>v.id===chosen);if(!c)return;let stories=c.stories;$('#detail').innerHTML='<h2>'+esc(c.name)+'</h2><p>Fortune 500 #'+c.fortuneRank+' · '+esc(c.sector)+'</p><span class="pill">'+c.signals+' AI news mentions</span>'+(c.capex?'<p><strong>2026 capex guidance: '+esc(c.capex.display)+'</strong><br>'+esc(c.capex.scope)+' · <a target="_blank" rel="noopener noreferrer" href="'+esc(c.capex.url)+'">Company source</a></p>':'<p>No comparable company-reported capex figure added yet.</p>')+'<h3>Recent stories</h3><button class="primary" id="companyScan">Scan this company now</button><p id="companyScanStatus" class="status"></p>'+(stories.length?stories.slice(0,5).map(s=>'<div class="story"><a target="_blank" rel="noopener noreferrer" href="'+esc(s.url)+'">'+esc(s.title)+'</a><small>'+esc(s.kind||'Dated news')+' · '+esc(s.publisher)+' · '+(s.published?new Date(s.published).toLocaleDateString():'')+'</small></div>').join(''):'<p>No matching stories returned. Try refreshing or search this company directly.</p>')+'<h3>Draft email</h3><label for="role">Recipient role</label><select id="role"><option>AI / Data leader</option><option>Technology leader</option><option>Finance leader</option><option>Operations leader</option></select><label for="story">Source story</label><select id="story">'+(stories.length?stories.slice(0,5).map((s,i)=>'<option value="'+i+'">'+esc(s.title)+'</option>').join(''):'<option value="-1">No current story</option>')+'</select><div id="email" class="email"></div><div class="actions"><button class="primary" id="copy">Copy email</button><a target="_blank" rel="noopener noreferrer" href="https://www.linkedin.com/search/results/people/?keywords='+encodeURIComponent(c.name+' AI data leader')+'">Find people</a></div>';function write(){let s=stories[+$('#story').value];$('#email').textContent='Subject: A question about '+c.name+'’s AI priorities\\n\\nHi [First name],\\n\\n'+(s?'I saw the recent story “'+s.title+'” ('+s.url+').':'I have been following '+c.name+'’s AI initiatives.')+'\\n\\nI work with teams evaluating where AI investment can create measurable value. I would be interested in how your '+$('#role').value.toLowerCase()+' team is prioritizing initiatives and measuring results this year.\\n\\nWould you be open to a brief conversation next week? If someone else owns this area, I would appreciate a pointer to the right person.\\n\\nBest,\\n[Your name]'}$('#companyScan').onclick=async()=>{let b=$('#companyScan');b.disabled=true;b.textContent='Scanning…';try{let r=await fetch('/api/company?rank='+c.fortuneRank);if(!r.ok)throw Error('Feed '+r.status);let fresh=await r.json();if(fresh.status==='live'){if(fresh.stories.length){c.stories=fresh.stories;c.signals=fresh.signals;c.status='live';$('#active').textContent=data.filter(v=>v.signals>0).length;$('#spendMentions').textContent=data.filter(v=>v.stories.some(s=>s.kind==='Spending mention')).length;rows();chart();detail()}else $('#companyScanStatus').textContent='No additional recent AI stories found. The dated snapshot remains visible.'}else $('#companyScanStatus').textContent='News feed unavailable. Existing dated stories remain visible.'}catch(e){$('#companyScanStatus').textContent='Scan unavailable: '+e.message}finally{if(document.body.contains(b)){b.disabled=false;b.textContent='Scan this company now'}}};$('#role').onchange=write;$('#story').onchange=write;$('#copy').onclick=async()=>{await navigator.clipboard.writeText($('#email').textContent);$('#copy').textContent='Copied';setTimeout(()=>$('#copy').textContent='Copy email',2000)};write()}async function scanAll(){let b=$('#refresh');b.disabled=true;let added=0,checked=0,failed=0;for(let n=0;n<20;n++){b.textContent='Scanning '+(n+1)+'/20';$('#status').textContent='Checking companies '+(n*20+1)+'–'+((n+1)*20)+' of 400';try{let r=await fetch('/api/scan?batch='+n);if(!r.ok)throw Error('batch '+n+' HTTP '+r.status);let x=await r.json();for(let item of x.companies){let c=data.find(v=>v.id===item.id);if(!c)continue;checked++;if(item.status!=='live'){failed++;continue}if(item.stories.length){c.stories=item.stories;c.signals=item.stories.length;c.status='live';added+=item.stories.length}}$('#active').textContent=data.filter(c=>c.signals>0).length;$('#spendMentions').textContent=data.filter(c=>c.stories.some(v=>v.kind==='Spending mention')).length;$('#missing').textContent=(data.length-data.filter(c=>c.signals>0).length)+' companies have no matched story in this scan';rows();chart();detail()}catch(e){failed+=20}}b.disabled=false;b.textContent='Scan 400 companies';$('#status').textContent=checked+' checked · '+data.filter(c=>c.signals>0).length+' with AI news · '+added+' new stories'+(failed?' · '+failed+' unavailable':'')}
async function load(fresh=false){let b=$('#refresh');b.disabled=true;b.textContent='Scanning…';$('#status').textContent=fresh?'Checking open news index':'Loading dated scan';try{let r=await fetch(fresh?'/api/scan?fresh=1':'/api/scan');if(!r.ok)throw Error('News service '+r.status);let x=await r.json();data=x.companies;$('#covered').textContent=data.length;$('#active').textContent=data.filter(c=>c.signals>0).length;$('#figures').textContent=data.filter(c=>c.capex).length;$('#spendMentions').textContent=data.filter(c=>c.stories.some(s=>s.kind==='Spending mention')).length;$('#missing').textContent=(data.length-data.filter(c=>c.signals>0).length)+' companies have no matched story in this snapshot';$('#updated').textContent='News snapshot '+new Date(x.updatedAt).toLocaleString()+(x.liveStatus==='not checked'?'':' · Live check '+(x.liveStatus==='ok'?'complete':'unavailable'));$('#status').textContent=data.filter(c=>c.stories.length).length+' companies with stories · '+data.length+' Fortune 500 tracked'+(x.liveStatus==='not checked'?' · press Scan 400 companies for an update':x.liveStatus==='ok'?' · '+x.liveAdded+' new':' · live source unavailable');$('#sector').innerHTML='<option value="">All sectors</option>'+[...new Set(data.map(c=>c.sector))].sort().map(s=>'<option>'+esc(s)+'</option>').join('');if(chosen===null)chosen=filtered()[0]?.id;pageNum=0;rows();chart();detail()}catch(e){$('#status').textContent='Scan failed: '+e.message;$('#rows').textContent='Could not load current news. Try again.'}finally{b.disabled=false;b.textContent='Scan 400 companies'}}['search','sector','sort'].forEach(i=>$('#'+i).addEventListener(i==='search'?'input':'change',()=>{pageNum=0;rows();chart()}));$('#coverage').onclick=()=>{showAll=!showAll;pageNum=0;$('#coverage').textContent=showAll?'Show companies with news':'Show all 400 companies';rows();chart()};$('#refresh').onclick=scanAll;load();</script></body></html>`;
export default {async fetch(request,env,ctx){void env;let u=new URL(request.url);if(u.pathname==='/')return new Response(page,{headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store'}});if(u.pathname==='/api/company'){let rank=Number(u.searchParams.get('rank'));let company=baseline.companies.find(c=>c.fortuneRank===rank);if(!company)return new Response('Not found',{status:404});return Response.json(await scan(company),{headers:{'cache-control':'no-store'}})}if(u.pathname==='/api/scan'){if(u.searchParams.has('batch')){let n=Number(u.searchParams.get('batch'));if(!Number.isInteger(n)||n<0||n>=20)return new Response('Bad batch',{status:400});let group=baseline.companies.slice(n*20,(n+1)*20),scanned=[];for(let i=0;i<group.length;i+=5)scanned.push(...await Promise.all(group.slice(i,i+5).map(scan)));return Response.json({companies:scanned,batch:n,totalBatches:20,checkedAt:new Date().toISOString()},{headers:{'cache-control':'no-store'}})}if(u.searchParams.get('fresh')!=='1')return Response.json({...baseline,liveStatus:'not checked'},{headers:{'cache-control':'no-store'}});let output=structuredClone(baseline);output.liveCheckedAt=new Date().toISOString();output.liveStatus='unavailable';try{let q='AI spending';let v='https://api.gdeltproject.org/api/v2/doc/doc?query='+encodeURIComponent(q)+'&mode=artlist&format=json&maxrecords=250&timespan=1week&sort=datedesc';let r=await fetch(v,{signal:AbortSignal.timeout(20000)});if(r.ok){let articles=(await r.json()).articles||[];let added=0;for(let c of output.companies){let found=articles.filter(a=>a.title&&a.url&&a.title.toLowerCase().includes(c.name.toLowerCase())).slice(0,3).map(a=>({title:a.title,url:a.url,published:a.seendate,publisher:a.domain||'',amount:null}));let urls=new Set(c.stories.map(s=>s.url));for(let item of found){if(!urls.has(item.url)){c.stories.unshift(item);urls.add(item.url);added++}}c.stories=c.stories.slice(0,8);c.signals=c.stories.length}output.liveStatus='ok';output.liveAdded=added}else output.liveStatus='HTTP '+r.status}catch(e){output.liveStatus=String(e)}return Response.json(output,{headers:{'cache-control':'no-store'}})}return new Response('Not found',{status:404})}};
